using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

[McpServerToolType]
public class WeatherTools
{
    [McpServerTool(Name = "get_forecast",
        Title = "Get Weather Forecast",
        ReadOnly = true,
        Destructive = false,
        OpenWorld = true)]
    [Description("Returns a multi-day weather forecast for the given latitude and longitude.")]
    public async Task<string> GetForecast(
        IHttpClientFactory httpClientFactory,
        [Description("Latitude of the location (-90 to 90).")] double latitude,
        [Description("Longitude of the location (-180 to 180).")] double longitude,
        [Description("Number of forecast days (1-16). Defaults to 3.")] int forecastDays = 3)
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + $"&daily=temperature_2m_max,temperature_2m_min,precipitation_sum"
                + $"&forecast_days={forecastDays}&timezone=auto";

        var response = await client.GetFromJsonAsync<ForecastResponse>(url);
        if (response?.Daily is null)
            return "No forecast data available.";

        var lines = new List<string>();
        for (int i = 0; i < response.Daily.Time.Count; i++)
        {
            lines.Add($"{response.Daily.Time[i]}: " +
                       $"High {response.Daily.TemperatureMax[i]}°C, " +
                       $"Low {response.Daily.TemperatureMin[i]}°C, " +
                       $"Precip {response.Daily.PrecipitationSum[i]} mm");
        }

        return string.Join("\n", lines);
    }

    [McpServerTool(Name = "get_current_weather",
        Title = "Get Current Weather",
        ReadOnly = true,
        Destructive = false,
        OpenWorld = true)]
    [Description("Returns current weather conditions for the given coordinates.")]
    public async Task<string> GetCurrentWeather(
        IHttpClientFactory httpClientFactory,
        [Description("Latitude of the location (-90 to 90).")] double latitude,
        [Description("Longitude of the location (-180 to 180).")] double longitude)
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,relative_humidity_2m,wind_speed_10m"
                + "&timezone=auto";

        var response = await client.GetFromJsonAsync<CurrentResponse>(url);
        if (response?.Current is null)
            return "No current weather data available.";

        return $"Temperature: {response.Current.Temperature}°C, "
             + $"Humidity: {response.Current.Humidity}%, "
             + $"Wind: {response.Current.WindSpeed} km/h";
    }
}

public record ForecastResponse(
    [property: JsonPropertyName("daily")] DailyData? Daily);

public record DailyData(
    [property: JsonPropertyName("time")] List<string> Time,
    [property: JsonPropertyName("temperature_2m_max")] List<double> TemperatureMax,
    [property: JsonPropertyName("temperature_2m_min")] List<double> TemperatureMin,
    [property: JsonPropertyName("precipitation_sum")] List<double> PrecipitationSum);

public record CurrentResponse(
    [property: JsonPropertyName("current")] CurrentData? Current);

public record CurrentData(
    [property: JsonPropertyName("temperature_2m")] double Temperature,
    [property: JsonPropertyName("relative_humidity_2m")] int Humidity,
    [property: JsonPropertyName("wind_speed_10m")] double WindSpeed);

